import networkx as nx
import itertools
import random

def check_graph(edges):
    G = nx.Graph()
    G.add_nodes_from(range(11))
    G.add_edges_from(edges)

    if G.number_of_edges() < 7 or G.number_of_edges() > 19:
        return False

    degrees = [d for n, d in G.degree()]
    if any(d < 3 for d in degrees) or any(d > 5 for d in degrees):
        return False

    # Check if bipartite (chi < 3)
    if nx.is_bipartite(G):
        return False

    # Check chromatic number <= 4
    # For small graphs, we can use exact coloring
    try:
        # nx.coloring.greedy_color is just an upper bound.
        # Let's use a more robust check if possible, but for 11 nodes, 
        # greedy might be okay or we can use a simple backtracking.
        # Actually, for 11 nodes, we can just check if it's 3-colorable.
        # If it's not 3-colorable, it might be 4-colorable.
        # If it's 3-colorable, it's definitely <= 4.
        # If it's not 3-colorable, we need to check if it's 4-colorable.
        # Actually, Brooks' Theorem: chi(G) <= Delta(G) unless G is complete or odd cycle.
        # Here Delta <= 5, so chi <= 5. We need chi <= 4.
        # Let's just use a simple backtracking to find the chromatic number.

        def is_k_colorable(G, k):
            color = {}
            def backtrack(node):
                if node == 11:
                    return True
                for c in range(k):
                    if all(color.get(neighbor) != c for neighbor in G.neighbors(node)):
                        color[node] = c
                        if backtrack(node + 1):
                            return True
                        del color[node]
                return False
            return backtrack(0)

        if not is_k_colorable(G, 4):
            return False

    except:
        return False

    return True

